for path in sorted(by):
    if path.endswith('.py'):
        src=subprocess.run(['git','show',f'HEAD:{path}'],capture_output=True,text=True).stdout.splitlines()
        def encl(L):
            for i in range(L-1,-1,-1):
                if re.match(r'(def |class )',src[i]): return re.match(r'(def \w+|class \w+)',src[i]).group(1)
                if re.match(r'\S',src[i]) and not src[i].startswith(('#',')',']','}')) and re.match(r'^[A-Z_]+ *=',src[i]): return src[i].split('=')[0].strip()
            return '<module>'
        ls=[f"{L}({encl(L)})" for L,_ in by[path]]
    else:
        ls=[str(L) for L,_ in by[path]]
    out.append(f"{path}: n={len(by[path])} :: "+", ".join(ls))
open(f"{S}/head_code_map.txt","w").write("\n".join(out))
print("\n".join(out))
